"use client"

import * as React from "react"
import * as ToggleGroupPrimitive from "@radix-ui/react-toggle-group"

import { useComposedRefs } from "@/lib/0db/refs"
import { cn } from "@/lib/utils"

type Run = { items: HTMLElement[]; l: number; r: number; t: number; h: number }
type Mark = { el: HTMLElement; items: HTMLElement[] }

/**
 * One mark per run of held words that stand side by side on a row: the slur over them, or the
 * parentheses round them. The mark reads --l, --r, --t and --h from the run's words: from the
 * italic you see, not the cell it shares with the wider or narrower roman, so the mark sits even
 * on both sides. Physical measurements, so right to left needs nothing more.
 *
 * As the held words change, a mark that covered one of a run's words stretches to fit it; another
 * mark that also did (two runs just joined) fades where it is; a run with no mark gets one, which
 * lands; a mark with no run lets go. With one held at a time, the mark glides from the old word to
 * the new one, leading edge first (data-dir). The engine also marks the first word of each wrapped
 * row (data-line-start), so no hairline stands at the start of a line.
 *
 * fingering: each held word carries the order it was held in (--n), set over the middle of the face
 * you see (--fx), and the group carries the number the next one would get (--next). Seeded from the
 * value's order, which is the order Radix keeps.
 */
function useMarks(single: boolean, fingering: boolean, seed: readonly string[]) {
  const ref = React.useRef<HTMLDivElement | null>(null)
  const first = React.useRef(seed)
  React.useLayoutEffect(() => {
    const root = ref.current
    const layer = root?.querySelector<HTMLElement>(":scope > .db-toggles-marks")
    if (!root || !layer) return
    let marks: Mark[] = []
    const all = () => [...root.querySelectorAll<HTMLElement>('[data-slot="toggle-group-item"]')]
    let order = first.current.flatMap((v) => all().filter((i) => i.dataset.value === v && i.dataset.state === "on"))

    // The face you see, left and right in px: held, the italic copy; otherwise the roman. They share
    // one cell (start-aligned on the first word of a line, centred elsewhere) but not one width.
    const face = (item: HTMLElement, k: number, rtl: boolean) => {
      const word = item.querySelector<HTMLElement>(":scope > .db-toggles-word")
      if (!word) {
        const r = item.getBoundingClientRect()
        const cs = getComputedStyle(item)
        return [r.left + parseFloat(cs.paddingLeft) * k, r.right - parseFloat(cs.paddingRight) * k]
      }
      if (item.dataset.state !== "on") {
        const r = word.firstElementChild!.getBoundingClientRect()
        return [r.left, r.right]
      }
      const cell = word.getBoundingClientRect()
      const w = parseFloat(getComputedStyle(word, "::after").width) * k
      const l = getComputedStyle(word).justifyItems.includes("center") ? (cell.left + cell.right - w) / 2 : rtl ? cell.right - w : cell.left
      return [l, l + w]
    }

    const place = (moving: boolean) => {
      // Resizes, fonts arriving and the first place are not a choice: the marks go straight there.
      if (!moving) root.setAttribute("data-still", "")
      const b = root.getBoundingClientRect()
      const k = b.width / root.offsetWidth || 1 // on-screen px per CSS px: a scaled ancestor would throw the marks off
      const rtl = getComputedStyle(root).direction === "rtl"
      const items = all()
      const runs: Run[] = []
      let run: Run | undefined
      let top: number | undefined
      for (const item of items) {
        const r = item.getBoundingClientRect()
        const turned = top !== undefined && Math.abs(r.top - top) > 1
        top = r.top
        item.toggleAttribute("data-line-start", turned)
      }
      for (const item of items) {
        const r = item.getBoundingClientRect()
        const turned = item.hasAttribute("data-line-start")
        const [fl, fr] = face(item, k, rtl)
        if (fingering) item.style.setProperty("--fx", `${((fl + fr) / 2 - r.left) / k}px`)
        if (item.dataset.state !== "on") run = undefined
        else {
          // The mark stands off the italic by the item's own padding, the room its parentheses hang in.
          const cs = getComputedStyle(item)
          const l = fl - parseFloat(cs.paddingLeft) * k
          const rr = fr + parseFloat(cs.paddingRight) * k
          if (run && !turned) {
            run.items.push(item)
            run.l = Math.min(run.l, l)
            run.r = Math.max(run.r, rr)
          } else runs.push((run = { items: [item], l, r: rr, t: r.top, h: r.height }))
        }
      }
      if (fingering) {
        const on = items.filter((i) => i.dataset.state === "on")
        order = order.filter((i) => on.includes(i)).concat(on.filter((i) => !order.includes(i)))
        order.forEach((i, n) => i.style.setProperty("--n", `"${n + 1}"`))
        root.style.setProperty("--next", `"${order.length + 1}"`)
      }

      const set = (mark: Mark, run: Run, glide = false) => {
        const { el } = mark
        const l = (run.l - b.left) / k
        const r = (b.right - run.r) / k
        const was = parseFloat(el.style.getPropertyValue("--l")) - parseFloat(el.style.getPropertyValue("--r"))
        if (glide) el.dataset.dir = l - r >= was ? "right" : "left"
        else delete el.dataset.dir
        el.style.setProperty("--l", `${l}px`)
        el.style.setProperty("--r", `${r}px`)
        el.style.setProperty("--t", `${(run.t - b.top) / k}px`)
        el.style.setProperty("--h", `${run.h / k}px`)
        el.toggleAttribute("data-muted", run.items.every((i) => i.hasAttribute("data-disabled")))
        mark.items = run.items
        return mark
      }
      const leave = (el: HTMLElement, how: "merge" | "release") => {
        el.setAttribute("data-leave", how)
        const done = () => el.remove()
        Promise.all(el.getAnimations({ subtree: true }).map((a) => a.finished)).then(done, done)
      }

      const claimed = new Set<Mark>()
      const next: Mark[] = []
      const fresh: Run[] = []
      for (const run of runs) {
        const over = marks.filter((m) => !claimed.has(m) && m.items.some((i) => run.items.includes(i)))
        if (!over.length) {
          fresh.push(run)
          continue
        }
        over.forEach((m) => claimed.add(m))
        over.slice(1).forEach((m) => leave(m.el, "merge"))
        next.push(set(over[0], run))
      }
      const entering: HTMLElement[] = []
      for (const run of fresh) {
        const left = single ? marks.find((m) => !claimed.has(m)) : undefined
        if (left) {
          claimed.add(left)
          next.push(set(left, run, moving))
          continue
        }
        const el = document.createElement("i")
        el.className = "db-toggles-mark"
        el.setAttribute("data-enter", "")
        layer.append(el)
        entering.push(el)
        next.push(set({ el, items: [] }, run))
      }
      marks.filter((m) => !claimed.has(m)).forEach((m) => leave(m.el, "release"))
      marks = next

      // Read once so the entering marks start from their first frame, then let them land.
      void root.offsetWidth
      entering.forEach((el) => el.removeAttribute("data-enter"))
      if (!moving) {
        void root.offsetWidth
        root.removeAttribute("data-still")
      }
    }

    place(false)
    // A choice moves the marks; the direction arriving (read as the group mounts) only puts them in place.
    const chose = new MutationObserver((list) => {
      const own = list.filter((m) => !layer.contains(m.target))
      if (own.length) place(!own.some((m) => m.attributeName === "dir"))
    })
    chose.observe(root, { attributes: true, attributeFilter: ["data-state", "data-disabled", "dir"], subtree: true, childList: true })
    const resize = new ResizeObserver(() => place(false))
    resize.observe(root)
    root.querySelectorAll('[data-slot="toggle-group-item"]').forEach((i) => resize.observe(i))
    document.fonts?.ready.then(() => place(false))
    return () => {
      chose.disconnect()
      resize.disconnect()
      layer.replaceChildren()
    }
  }, [single, fingering])
  return ref
}

type ToggleGroupProps = React.ComponentProps<typeof ToggleGroupPrimitive.Root> & {
  /**
   * How held words are marked. slur: hairlines stand between the words, and a run of held neighbours
   * is tied under one slur. bracket: no hairlines; the held words are set in parentheses, and
   * neighbours share one pair. fingering: each held word carries, over it, the number of its turn
   * (for type="multiple"). margin: the words stand in a column beside a hairline and an empty
   * margin; a held word crosses the hairline into the margin, like a book's side head.
   */
  variant?: "slur" | "bracket" | "fingering" | "margin"
}

/**
 * Words in a row that you can hold down. type="single" holds one at a time, "multiple" any number.
 * Held, a word is yours, so it turns italic; its mark (a slur, or parentheses) stretches over the
 * held words beside it and glides to a new choice. Radix keeps the roving focus and the arrow keys.
 */
function ToggleGroup({ className, variant = "slur", dir, children, ref, ...props }: ToggleGroupProps) {
  const held = props.value ?? props.defaultValue
  const ownRef = useMarks(props.type === "single", variant === "fingering", typeof held === "string" ? [held] : (held ?? []))
  // Radix writes dir="ltr" on the group unless told otherwise, which would turn a right-to-left page's
  // words and arrow keys around. Without a dir, the group takes the direction of the page around it,
  // read as the group mounts, before the first paint.
  const [around, setAround] = React.useState<"rtl">()
  const composedRef = useComposedRefs(React.useCallback((node: HTMLDivElement | null) => {
    ownRef.current = node
    const up = node?.parentElement
    if (!dir && up && getComputedStyle(up).direction === "rtl") setAround("rtl")
  }, [dir, ownRef]), ref)
  return (
    <ToggleGroupPrimitive.Root
      ref={composedRef}
      data-slot="toggle-group"
      data-variant={variant}
      dir={dir ?? around}
      className={cn("db-toggles", className)}
      {...props}
    >
      {children}
      <span data-slot="toggle-group-marks" className="db-toggles-marks" aria-hidden="true" />
    </ToggleGroupPrimitive.Root>
  )
}

type ToggleGroupItemProps = React.ComponentProps<typeof ToggleGroupPrimitive.Item> & {
  /** Pins a state for documentation ("hover", "focus"); set on the root. */
  "data-force"?: string
}

/**
 * One word in the group. A plain-text word shares its grid cell with an italic copy of itself (drawn
 * by the stylesheet from data-text), so it is always as wide as its wider state and nothing beside it
 * moves when it turns.
 */
function ToggleGroupItem({ className, children, ...props }: ToggleGroupItemProps) {
  return (
    <ToggleGroupPrimitive.Item data-slot="toggle-group-item" data-value={props.value} className={cn("db-toggles-item", className)} {...props}>
      {typeof children === "string" ? (
        <span className="db-toggles-word" data-text={children}>
          <span>{children}</span>
        </span>
      ) : (
        children
      )}
    </ToggleGroupPrimitive.Item>
  )
}

export { ToggleGroup, ToggleGroupItem, type ToggleGroupProps, type ToggleGroupItemProps }

@layer components {
  /* ── db-toggles ── toggle group: words in a row that you can hold down. Held, a word is yours and turns
     italic, and one mark stretches over each run of held neighbours: a slur (the score's sign for notes
     played together), or, in the bracket variant, a pair of parentheses. The marks are drawn by
     toggle-group.tsx from --l, --r, --t and --h; everything else is here, so the group needs no other item. */
  .db-toggles {
    --gap: 1.3em;  /* between two words */
    --room: 0.62em; /* over the words, where the slur arches */
    position: relative; display: flex; flex-wrap: wrap; align-items: baseline; column-gap: var(--gap); row-gap: var(--db-space-2);
    font-size: var(--db-mp); line-height: 1.2; letter-spacing: var(--db-mp-tr);
  }
  .db-toggles-item {
    position: relative; appearance: none; border: 0; background: none; margin: 0; padding: var(--room) 0 calc(var(--room) / 2);
    font: inherit; letter-spacing: inherit; color: var(--db-graphite); cursor: pointer; -webkit-tap-highlight-color: transparent;
    /* The focus ring rests open and invisible, so it can close onto the word you arrive at. It rings the
       whole button, so it holds the word together with its mark: the slur over it, or its parentheses. */
    outline: var(--db-stroke) solid transparent; outline-offset: 12px;
    transition: color var(--db-allegro), outline-color var(--db-allegro), outline-offset var(--db-moderato) var(--db-spiccato);
  }
  .db-toggles-item:is(:focus-visible, [data-force~="focus"]) { outline-color: var(--db-accent); outline-offset: 5px; }
  .db-toggles-item:is(:hover, [data-force~="hover"]):not(:disabled),
  .db-toggles-item[data-state="on"] { color: var(--db-ink); }
  .db-toggles-item:disabled { color: var(--db-pencil); opacity: 0.55; cursor: not-allowed; }

  /* The word and its italic copy share one cell: the roman sinks away as the italic rises into its place.
     Centred, the spare width splits evenly either side; the first word of each line starts at the cell's
     start edge instead, so the line lines up with the label above it. */
  .db-toggles-word { display: inline-grid; justify-items: center; align-items: baseline; transition: translate var(--db-allegro) var(--db-exhale); }
  .db-toggles-item:is(:first-child, [data-line-start]) .db-toggles-word { justify-items: start; }
  /* The roman carries its own pencil sketch, so the sketch sits even on the word you see, whatever the cell's width. */
  .db-toggles-word > span { position: relative; --up: -0.12em; }
  .db-toggles-word > span,
  .db-toggles-word::after { grid-area: 1 / 1; transition: opacity var(--db-moderato) var(--db-breath), translate var(--db-moderato) var(--db-exhale); }
  .db-toggles-word::after {
    content: attr(data-text) / "";
    font-family: var(--db-expression); font-style: italic; font-weight: 400; font-size: calc(var(--db-expression-scale) * 1em); line-height: 1; letter-spacing: 0;
    opacity: 0; translate: 0 0.16em;
  }
  .db-toggles-item[data-state="on"] .db-toggles-word > span { opacity: 0; translate: 0 -0.16em; }
  .db-toggles-item[data-state="on"] .db-toggles-word::after { opacity: 1; translate: 0 0; }
  /* A word that isn't plain text has no copy to turn to, so it turns in place. */
  .db-toggles-item[data-state="on"]:not(:has(.db-toggles-word)) { font-family: var(--db-expression); font-style: italic; }
  /* Pressing sets the word down a hair before it turns. */
  .db-toggles-item:active:not(:disabled) .db-toggles-word { translate: 0 1px; }

  /* The marks: one per run of held neighbours, laid over the words and moved by their edges. */
  .db-toggles-marks { position: absolute; inset: 0; pointer-events: none; }
  .db-toggles-mark {
    position: absolute; left: var(--l); right: var(--r); top: var(--t); height: var(--h);
    container-type: inline-size; color: var(--db-ink);
    transition: left var(--db-moderato) var(--db-exhale), right var(--db-moderato) var(--db-exhale), top var(--db-moderato) var(--db-breath), height var(--db-moderato) var(--db-breath);
  }
  /* Gliding to a new word (one at a time), the leading edge sets off first and the other follows: legato. */
  .db-toggles-mark[data-dir] { transition-duration: var(--db-andante); transition-timing-function: var(--db-breath); }
  .db-toggles-mark[data-dir="right"] { transition-delay: calc(var(--db-arpeggio) * 3), 0s, 0s, 0s; }
  .db-toggles-mark[data-dir="left"] { transition-delay: 0s, calc(var(--db-arpeggio) * 3), 0s, 0s; }
  .db-toggles-mark[data-muted] { color: var(--db-pencil); opacity: 0.55; }
  .db-toggles[data-still] .db-toggles-mark,
  .db-toggles[data-still] .db-toggles-mark::before,
  .db-toggles[data-still] .db-toggles-mark::after { transition: none; }

  /* ── slur (the default) ── hairlines stand between the words; the held ones are tied under a slur */
  .db-toggles[data-variant="slur"] > .db-toggles-item + .db-toggles-item::before {
    content: ""; position: absolute; inset-inline-start: calc(var(--gap) / -2); bottom: calc(var(--room) / 2 + 0.08em); height: 1.02em;
    border-inline-start: var(--db-hairline) solid var(--db-rule-strong); transform-origin: 50% 100%; pointer-events: none;
    transition: scale var(--db-moderato) var(--db-breath);
  }
  /* Two held neighbours are one phrase: the hairline between them lies down under the slur. */
  .db-toggles[data-variant="slur"] > .db-toggles-item[data-state="on"] + .db-toggles-item[data-state="on"]::before { scale: 1 0; }
  .db-toggles[data-variant="slur"] > .db-toggles-item[data-line-start]::before { content: none; }
  /* The slur is engraved, not drawn: one border on a half-ellipse, so it swells in the middle and tapers to
     points. It bows deeper the further it reaches (cqi is the mark's own width). */
  .db-toggles[data-variant="slur"] :is(.db-toggles-mark, .db-toggles-item:not(:has(> .db-toggles-word)), .db-toggles-word > span)::after {
    content: ""; position: absolute; inset-inline: 0.1em; top: var(--up, calc(var(--room) - 0.12em)); height: clamp(0.2em, 3.2cqi, 0.44em); translate: 0 -100%;
    border-top: calc(var(--db-stroke) * 1.4) solid currentColor; border-radius: 50% 50% 0 0 / 100% 100% 0 0;
    transform-origin: 50% 100%; pointer-events: none;
  }
  .db-toggles[data-variant="slur"] .db-toggles-mark::after { transition: scale var(--db-moderato) var(--db-spiccato), opacity var(--db-allegro); }
  .db-toggles[data-variant="slur"] .db-toggles-mark[data-enter]::after { scale: 0.4 0; opacity: 0; }
  .db-toggles[data-variant="slur"] .db-toggles-mark[data-leave="release"]::after { scale: 0.4 0; opacity: 0; transition-timing-function: var(--db-breath); }
  /* Pointing sketches the slur in pencil, from the middle out, over the roman. */
  .db-toggles[data-variant="slur"] :is(.db-toggles-item:not(:has(> .db-toggles-word)), .db-toggles-word > span)::after {
    height: 0.22em; border-top-width: var(--db-hairline); border-top-color: var(--db-rule-strong);
    scale: 0 1; opacity: 0; transition: scale var(--db-moderato) var(--db-exhale), opacity var(--db-allegro);
  }
  .db-toggles[data-variant="slur"] .db-toggles-item:is(:hover, [data-force~="hover"]):not(:disabled, [data-state="on"]) > .db-toggles-word > span::after,
  .db-toggles[data-variant="slur"] .db-toggles-item:not(:has(> .db-toggles-word)):is(:hover, [data-force~="hover"]):not(:disabled, [data-state="on"])::after { scale: 1; opacity: 1; }

  /* ── bracket ── no hairlines: the held words are set in parentheses, after 20(25), and neighbours share one pair */
  /* The room for the parentheses hangs into the margin, so the words at rest start where the label does. */
  .db-toggles[data-variant="bracket"] { --gap: 0.2em; --room: 0em; --pad: 0.55em; row-gap: var(--db-space-3); margin-inline: calc(var(--pad) * -1); }
  /* The ring already stands clear of the word by the room for the parentheses, so it closes onto the button's edge. */
  .db-toggles[data-variant="bracket"] .db-toggles-item { padding-inline: var(--pad); }
  .db-toggles[data-variant="bracket"] .db-toggles-item:is(:focus-visible, [data-force~="focus"]) { outline-offset: 1px; }
  .db-toggles[data-variant="bracket"] :is(.db-toggles-mark, .db-toggles-item:not(:has(> .db-toggles-word)), .db-toggles-word > span)::before,
  .db-toggles[data-variant="bracket"] :is(.db-toggles-mark, .db-toggles-item:not(:has(> .db-toggles-word)), .db-toggles-word > span)::after {
    position: absolute; inset-block: 0; display: grid; align-items: center; pointer-events: none;
    font-family: var(--db-expression); font-style: italic; font-weight: 400; font-size: calc(var(--db-expression-scale) * 1.18em); line-height: 1;
    direction: ltr; /* a parenthesis mirrors in right-to-left text; these are placed by hand, so they mustn't */
    transition: translate var(--db-moderato) var(--db-spiccato), opacity var(--db-allegro), color var(--db-allegro);
  }
  .db-toggles[data-variant="bracket"] :is(.db-toggles-mark, .db-toggles-item:not(:has(> .db-toggles-word)), .db-toggles-word > span)::before { content: "(" / ""; left: var(--side, 0); }
  .db-toggles[data-variant="bracket"] :is(.db-toggles-mark, .db-toggles-item:not(:has(> .db-toggles-word)), .db-toggles-word > span)::after { content: ")" / ""; right: var(--side, 0); }
  /* Over the roman, the pencil pair stands off it by the same room the ink pair keeps round the italic. */
  .db-toggles[data-variant="bracket"] .db-toggles-word > span { --side: calc(var(--pad) * -1); }
  .db-toggles[data-variant="bracket"] .db-toggles-mark:is([data-enter], [data-leave="release"])::before { translate: -0.35em 0; opacity: 0; }
  .db-toggles[data-variant="bracket"] .db-toggles-mark:is([data-enter], [data-leave="release"])::after { translate: 0.35em 0; opacity: 0; }
  /* Pointing sketches a pair in pencil, standing a little apart; holding closes the ink pair in. */
  .db-toggles[data-variant="bracket"] :is(.db-toggles-item:not(:has(> .db-toggles-word)), .db-toggles-word > span)::before,
  .db-toggles[data-variant="bracket"] :is(.db-toggles-item:not(:has(> .db-toggles-word)), .db-toggles-word > span)::after { color: var(--db-rule-strong); opacity: 0; }
  .db-toggles[data-variant="bracket"] :is(.db-toggles-item:not(:has(> .db-toggles-word)), .db-toggles-word > span)::before { translate: -0.3em 0; }
  .db-toggles[data-variant="bracket"] :is(.db-toggles-item:not(:has(> .db-toggles-word)), .db-toggles-word > span)::after { translate: 0.3em 0; }
  .db-toggles[data-variant="bracket"] .db-toggles-item:is(:hover, [data-force~="hover"]):not(:disabled, [data-state="on"]) > .db-toggles-word > span::before,
  .db-toggles[data-variant="bracket"] .db-toggles-item:not(:has(> .db-toggles-word)):is(:hover, [data-force~="hover"]):not(:disabled, [data-state="on"])::before { translate: -0.12em 0; opacity: 1; }
  .db-toggles[data-variant="bracket"] .db-toggles-item:is(:hover, [data-force~="hover"]):not(:disabled, [data-state="on"]) > .db-toggles-word > span::after,
  .db-toggles[data-variant="bracket"] .db-toggles-item:not(:has(> .db-toggles-word)):is(:hover, [data-force~="hover"]):not(:disabled, [data-state="on"])::after { translate: 0.12em 0; opacity: 1; }

  /* Merged into a neighbour's mark, a mark fades where it stands while the other stretches over it. */
  .db-toggles-mark[data-leave="merge"]::before,
  .db-toggles-mark[data-leave="merge"]::after { opacity: 0; transition: opacity var(--db-moderato) var(--db-breath); }

  /* ── fingering ── after the score's fingering, the small numbers over the notes that say which finger plays each,
     and the "01" of "Less is more.". No hairlines: each held word carries, over the middle of it, the number of its
     turn, the order you held them in (the value's order). The numbers are yours, so they're italic. Pointing at a word
     sketches in pencil the number it would get; holding inks it and it lands on the word; letting one go counts the
     later ones down. Meant for type="multiple"; held one at a time, the number is always 1. */
  .db-toggles[data-variant="fingering"] { --room: 1.15em; }
  .db-toggles[data-variant="fingering"] .db-toggles-item::after {
    content: var(--next, "") / ""; position: absolute; top: 0; left: var(--fx, 50%); translate: -50% -0.3em; pointer-events: none;
    font-family: var(--db-expression); font-style: italic; font-weight: 400; font-size: calc(var(--db-expression-scale) * 0.62em); line-height: 1; letter-spacing: 0;
    font-variant-numeric: lining-nums tabular-nums; color: var(--db-rule-strong); opacity: 0;
    transition: opacity var(--db-allegro), translate var(--db-moderato) var(--db-spiccato), left var(--db-moderato) var(--db-exhale), color var(--db-allegro);
  }
  .db-toggles[data-variant="fingering"] .db-toggles-item:is(:hover, [data-force~="hover"]):not(:disabled, [data-state="on"])::after { opacity: 1; translate: -50% -0.12em; }
  .db-toggles[data-variant="fingering"] .db-toggles-item[data-state="on"]::after { content: var(--n, "") / ""; color: var(--db-ink); opacity: 1; translate: -50% 0; }
  .db-toggles[data-variant="fingering"] .db-toggles-item[data-state="on"]:disabled::after { color: var(--db-pencil); }

  /* ── margin ── after the book's side head, set in the margin beside the column it heads. One hairline stands
     between an empty margin and the column of words; a held word crosses it. At rest a word stands in the column,
     flush against the rule; held, it steps over into the margin and turns italic, flush against the rule's other
     side, so what you hold reads down the margin and the rest down the column. The margin is as wide as the column
     (two equal tracks), so the widest word has room to cross. Pointing leans the word toward the rule. */
  .db-toggles[data-variant="margin"] {
    --dir: 1; --gap: 0.6em; display: inline-grid; grid-template-columns: 1fr 1fr; column-gap: calc(var(--gap) * 2); row-gap: 0;
  }
  .db-toggles[data-variant="margin"]:is([dir="rtl"], [dir="rtl"] *):not([dir="ltr"]) { --dir: -1; }
  .db-toggles[data-variant="margin"]::before {
    content: ""; position: absolute; inset-block: 0.2em; inset-inline-start: 50%; margin-inline-start: calc(var(--db-hairline) / -2);
    border-inline-start: var(--db-hairline) solid var(--db-rule-strong); pointer-events: none;
  }
  .db-toggles[data-variant="margin"] .db-toggles-item {
    --k: 0; --lean: 0em; grid-column: 2; padding-block: 0.12em; text-align: start;
    translate: calc(((-100% - var(--gap) * 2) * var(--k) - var(--lean)) * var(--dir)) 0;
    transition: color var(--db-allegro), outline-color var(--db-allegro), outline-offset var(--db-moderato) var(--db-spiccato), translate var(--db-moderato) var(--db-exhale);
  }
  .db-toggles[data-variant="margin"] .db-toggles-item:is(:hover, [data-force~="hover"]):not(:disabled, [data-state="on"]) { --lean: calc(var(--gap) / 2); }
  .db-toggles[data-variant="margin"] .db-toggles-item[data-state="on"] { --k: 1; }
  /* The roman stands at the column's edge, the italic at the margin's, each flush against the rule. */
  .db-toggles[data-variant="margin"] .db-toggles-word { display: grid; justify-items: start; }
  .db-toggles[data-variant="margin"] .db-toggles-word::after { justify-self: end; }

  @media (forced-colors: active) {
    .db-toggles { forced-color-adjust: none; --db-ink: ButtonText; --db-graphite: ButtonText; --db-pencil: GrayText; --db-rule-strong: GrayText; --db-accent: Highlight; }
    .db-toggles-mark { color: Highlight; }
  }
}
